/// Strips path/query from an RPC URL so it's safe to log (RPC URLs commonly embed
/// API keys in the path, e.g. `https://rpc.ankr.com/eth_sepolia/<key>`).
fn redact_url(url: &str) -> String {
    match url.split_once("://") {
        Some((scheme, rest)) => {
            // Secrets can appear in the path (`/eth_sepolia/<key>`), the query string
            // (`?apikey=<key>`), or userinfo (`user:pass@host`) - strip all three.
            let host_and_after = rest.split_once('@').map_or(rest, |(_, after)| after);
            let host = host_and_after
                .split(['/', '?', '#'])
                .next()
                .unwrap_or(host_and_after);
            format!("{scheme}://{host}")
        }
        None => "unknown".to_string(),
    }
}

fn build_http_client() -> reqwest::Client {
    reqwest::Client::builder()
        .connect_timeout(Duration::from_secs(10))
        .timeout(RPC_TIMEOUT)
        .build()
        .expect("Failed to build HTTP client")
}

fn build_provider_from_urls(urls: &[String], wallet: &EthereumWallet) -> DynProvider<Ethereum> {
    let http_client = build_http_client();

    if urls.len() == 1 {
        let transport = Http::with_client(http_client, urls[0].parse().expect("Invalid RPC URL"));
        let client = RpcClient::builder().transport(transport, false);
        return DynProvider::new(
            ProviderBuilder::new()
                .wallet(wallet.clone())
                .connect_client(client)
        );
    }

    let fallback = FallbackLayer::default()
        .with_active_transport_count(NonZeroUsize::new(3).unwrap());

    let transports: Vec<_> = urls.iter()
        .map(|url| ErrorAwareTransport {
            inner: Http::with_client(http_client.clone(), url.parse().expect("Invalid RPC URL")),
            label: redact_url(url),
        })
        .collect();

    let transport = ServiceBuilder::new()
        .layer(fallback)
        .service(transports);

    let client = RpcClient::builder().transport(transport, false);
    DynProvider::new(
        ProviderBuilder::new()
            .wallet(wallet.clone())
            .connect_client(client)
    )
}

impl ValidatorConfig {
    fn build_provider(&self, chain_id: u64) -> DynProvider<Ethereum> {
        let chain = self.chains.get(&chain_id).expect("Chain not found");
        build_provider_from_urls(&chain.rpc_urls, &self.wallet)
    }

    pub fn build_routes(&self) -> Vec<Route> {
        let arb_provider = self.build_provider(42161);
        let eth_provider = self.build_provider(1);
        let gnosis_provider = self.build_provider(100);

        vec![
            Route {
                name: "ARB_TO_ETH",
                inbox_chain_id: 42161,
                inbox_address: self.inbox_arb_to_eth,
                inbox_provider: arb_provider.clone(),
                inbox_avg_block_millis: 250,
                outbox_chain_id: 1,
                outbox_address: self.outbox_arb_to_eth,
                outbox_provider: eth_provider.clone(),
                weth_address: self.chains.get(&1).expect("Ethereum").deposit_token,
                settings: RouteSettings::test_defaults(),
            },
            Route {
                name: "ARB_TO_GNOSIS",
                inbox_chain_id: 42161,
                inbox_address: self.inbox_arb_to_gnosis,
                inbox_provider: arb_provider.clone(),
                inbox_avg_block_millis: 250,
                outbox_chain_id: 100,
                outbox_address: self.outbox_arb_to_gnosis,
                outbox_provider: gnosis_provider.clone(),
                weth_address: self.chains.get(&100).expect("Gnosis").deposit_token,
                settings: RouteSettings::test_defaults(),
            },
        ]
    }

    fn parse_rpc_urls(env_var: &str) -> Vec<String> {
        std::env::var(env_var)
            .expect(&format!("{} must be set", env_var))
            .split(',')
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect()
    }

    pub fn from_env() -> Result<Self, Box<dyn std::error::Error + Send + Sync>> {

        let arbitrum_rpcs = Self::parse_rpc_urls("ARBITRUM_RPC_URL");
        let ethereum_rpcs = Self::parse_rpc_urls("ETHEREUM_RPC_URL");
        let gnosis_rpcs = Self::parse_rpc_urls("GNOSIS_RPC_URL");
        let weth_gnosis = Address::from_str(
            &std::env::var("WETH_GNOSIS")
                .expect("WETH_GNOSIS must be set")
        )?;

        let private_key = std::env::var("PRIVATE_KEY")
            .or_else(|_| std::fs::read_to_string("/run/secrets/validator_key")
                .map(|s| s.trim().to_string()))
            .expect("PRIVATE_KEY not set or /run/secrets/validator_key not found");

        use alloy::signers::local::PrivateKeySigner;
        let signer = PrivateKeySigner::from_str(&private_key)?;
        let wallet = EthereumWallet::from(signer);

        let mut chains = HashMap::new();
        chains.insert(42161, ChainInfo {
            name: "Arbitrum".to_string(),
            rpc_urls: arbitrum_rpcs,
            deposit_token: None,
            avg_block_millis: 250,
        });
        chains.insert(1, ChainInfo {
            name: "Ethereum".to_string(),
            rpc_urls: ethereum_rpcs,
            deposit_token: None,
            avg_block_millis: 12000,
        });
        chains.insert(100, ChainInfo {
            name: "Gnosis".to_string(),
            rpc_urls: gnosis_rpcs,
            deposit_token: Some(weth_gnosis),
            avg_block_millis: 5000,
        });

        let inbox_arb_to_eth = Address::from_str(
            &std::env::var("VEA_INBOX_ARB_TO_ETH")
                .expect("VEA_INBOX_ARB_TO_ETH must be set")
        )?;
        let outbox_arb_to_eth = Address::from_str(
            &std::env::var("VEA_OUTBOX_ARB_TO_ETH")
                .expect("VEA_OUTBOX_ARB_TO_ETH must be set")
        )?;
        let inbox_arb_to_gnosis = Address::from_str(
            &std::env::var("VEA_INBOX_ARB_TO_GNOSIS")
                .expect("VEA_INBOX_ARB_TO_GNOSIS must be set")
        )?;
        let outbox_arb_to_gnosis = Address::from_str(
            &std::env::var("VEA_OUTBOX_ARB_TO_GNOSIS")
                .expect("VEA_OUTBOX_ARB_TO_GNOSIS must be set")
        )?;
        let arb_outbox = Address::from_str(
            &std::env::var("ARB_OUTBOX")
                .expect("ARB_OUTBOX must be set")
        )?;

        let make_claims = std::env::var("MAKE_CLAIMS")
            .map(|v| v.to_lowercase() == "true" || v == "1")
            .expect("MAKE_CLAIMS must be set");

        let sequencer_inbox = std::env::var("SEQUENCER_INBOX")
            .ok()
            .filter(|s| !s.is_empty())
            .map(|s| Address::from_str(&s).expect("Invalid SEQUENCER_INBOX address"));

        let ethereum_provider = build_provider_from_urls(
            &chains.get(&1).expect("Ethereum chain not configured").rpc_urls,
            &wallet,
        );

        Ok(Self {
            private_key,
            wallet,
            chains,
            inbox_arb_to_eth,
            outbox_arb_to_eth,
            inbox_arb_to_gnosis,
            outbox_arb_to_gnosis,
            arb_outbox,
            sequencer_inbox,
            ethereum_provider,
            make_claims,
        })
    }
}

/// Tests for the failover classification layer and URL redaction.
///
/// `ErrorAwareTransport` sits on the boundary between "this endpoint is broken" and
/// "the contract said no". Getting that boundary wrong in either direction is a real
/// hazard: too eager, and a contract revert gets rewritten into a transport error,
/// destroying the `"Invalid claim."` substring the dispatcher reschedules on; too lax,
/// and a fast-failing misconfigured endpoint wins the fallback race forever.
#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_support::{Fault, FaultTransport};
    use alloy::providers::Provider;

    #[test]
    fn infra_errors_are_classified_as_endpoint_failures() {
        assert!(is_infra_rpc_error(-32603, "internal error"));
        assert!(is_infra_rpc_error(-32005, "limit exceeded"));
        assert!(is_infra_rpc_error(-32000, "Unauthorized"));
        assert!(is_infra_rpc_error(-32000, "invalid API key"));
        assert!(is_infra_rpc_error(-32000, "rate limit exceeded"));
        assert!(is_infra_rpc_error(429, "Too Many Requests"));
    }

    #[test]
    fn a_contract_revert_is_never_reclassified() {
        // The outbox reverts with "Invalid claim." whenever the preimage a task holds no
        // longer matches `claimHashes[epoch]` - the normal, expected outcome of losing a
        // race. Rewriting it into a transport error would blank the dispatcher's
        // `contains("Invalid claim")` arm, and the task would be dropped or retried on
        // the wrong schedule instead of being re-derived against the current claim.
        assert!(!is_infra_rpc_error(3, "execution reverted: Invalid claim."));
        assert!(!is_infra_rpc_error(
            -32000,
            "execution reverted: Invalid claim."
        ));
        // -32000 is a provider-defined catch-all; several nodes use it for plain reverts,
        // which is why the code alone must not decide.
        assert!(!is_infra_rpc_error(-32000, "execution reverted"));
        assert!(!is_infra_rpc_error(-32015, "VM execution error"));
    }

    fn wrapped(fault: impl Fn() -> Fault + Send + Sync + 'static) -> DynProvider<Ethereum> {
        let transport = ErrorAwareTransport {
            inner: FaultTransport::new(move |_| fault()),
            label: "https://fake.invalid".to_string(),
        };
        let client = RpcClient::builder().transport(transport, false);
        DynProvider::new(ProviderBuilder::new().connect_client(client))
    }

    #[tokio::test]
    async fn an_infra_error_over_http_200_surfaces_as_a_transport_error() {
        // HTTP 200 with a JSON-RPC error body: the shape `FallbackLayer` does not score
        // down on its own. Only by turning it into a transport error does the fan-out
        // actually route around the endpoint.
        let provider = wrapped(|| Fault::RpcError {
            code: -32603,
            message: "internal error".to_string(),
        });

        let err = provider
            .get_block_number()
            .await
            .expect_err("an infra-level error is not a usable answer");
        let msg = err.to_string();
        assert!(msg.contains("error code -32603"), "unexpected message: {msg}");
        assert!(
            matches!(err, alloy::transports::RpcError::Transport(_)),
            "must be a transport error, or the fallback layer will not fail over: {msg}"
        );
    }

    #[tokio::test]
    async fn a_revert_passes_through_with_its_message_intact() {
        let provider = wrapped(|| Fault::RpcError {
            code: 3,
            message: "execution reverted: Invalid claim.".to_string(),
        });

        let err = provider
            .get_block_number()
            .await
            .expect_err("the node refused the call");
        assert!(
            err.to_string().contains("Invalid claim."),
            "the revert string the dispatcher matches on must survive: {err}"
        );
        assert!(
            matches!(err, alloy::transports::RpcError::ErrorResp(_)),
            "a revert is an application answer, not a broken endpoint"
        );
    }

    #[test]
    fn redaction_strips_every_place_an_api_key_hides() {
        assert_eq!(
            redact_url("https://rpc.example.com/eth_sepolia/deadbeefkey"),
            "https://rpc.example.com"
        );
        assert_eq!(
            redact_url("https://rpc.example.com?apikey=deadbeefkey"),
            "https://rpc.example.com"
        );
        assert_eq!(
            redact_url("https://user:secret@rpc.example.com/v1"),
            "https://rpc.example.com"
        );
        assert_eq!(redact_url("not a url"), "unknown");
    }
}

