pub fn check_finality_config(config: &ValidatorConfig) {
    if config.sequencer_inbox.is_none() {
        panic!("FATAL: SEQUENCER_INBOX must be set for L2 finality verification");
    }
    info!(logger = "Startup", sequencer_inbox = ?config.sequencer_inbox.unwrap(), "Finality config OK");
}

const TIMING_SAFETY_BUFFER_SECS: u64 = 10 * 60;

pub async fn check_rpc_health(routes: &[Route]) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    info!(logger = "Startup", "Checking RPC endpoint health");

    let arb_provider = &routes[0].inbox_provider;
    let eth_provider = &routes[0].outbox_provider;
    let gnosis_provider = &routes[1].outbox_provider;

    let arb_block = crate::retry_rpc("check Arbitrum RPC health", || async { arb_provider.get_block_number().await }).await
        .map_err(|e| format!("FATAL: Arbitrum RPC unreachable or unhealthy: {e}"))?;
    info!(logger = "Startup", chain = "Arbitrum", block = arb_block, "RPC healthy");
    let eth_block = crate::retry_rpc("check Ethereum RPC health", || async { eth_provider.get_block_number().await }).await
        .map_err(|e| format!("FATAL: Ethereum RPC unreachable or unhealthy: {e}"))?;
    info!(logger = "Startup", chain = "Ethereum", block = eth_block, "RPC healthy");
    let gnosis_block = crate::retry_rpc("check Gnosis RPC health", || async { gnosis_provider.get_block_number().await }).await
        .map_err(|e| format!("FATAL: Gnosis RPC unreachable or unhealthy: {e}"))?;
    info!(logger = "Startup", chain = "Gnosis", block = gnosis_block, "RPC healthy");
    Ok(())
}

pub async fn check_balances(c: &ValidatorConfig, routes: &[Route]) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let wallet_address = c.wallet.default_signer().address();
    let eth_provider = routes[0].outbox_provider.clone();
    let gnosis_provider = routes[1].outbox_provider.clone();

    let eth_outbox = IVeaOutbox::new(c.outbox_arb_to_eth, eth_provider.clone());
    let gnosis_outbox = IVeaOutbox::new(c.outbox_arb_to_gnosis, gnosis_provider.clone());

    let eth_deposit = eth_outbox.deposit().call().await?;
    let eth_balance = eth_provider.get_balance(wallet_address).await?;
    if eth_balance < eth_deposit {
        panic!("FATAL: Insufficient ETH balance. Need {} wei for deposit, have {} wei", eth_deposit, eth_balance);
    }

    let gnosis_deposit = gnosis_outbox.deposit().call().await?;
    let weth_addr = c.chains.get(&100).expect("Gnosis").deposit_token
        .expect("Gnosis should use WETH");
    let weth = IWETH::new(weth_addr, gnosis_provider.clone());
    let weth_balance = weth.balanceOf(wallet_address).call().await?;
    if weth_balance < gnosis_deposit {
        panic!("FATAL: Insufficient WETH balance on Gnosis. Need {} wei for deposit, have {} wei", gnosis_deposit, weth_balance);
    }

    let xdai_balance = gnosis_provider.get_balance(wallet_address).await?;
    let xdai_min = U256::from(10_000_000_000_000_000u64);
    if xdai_balance < xdai_min {
        panic!("FATAL: Insufficient xDAI on Gnosis for gas. Need {} wei, have {} wei", xdai_min, xdai_balance);
    }
    info!(logger = "Startup", eth = %eth_balance, weth = %weth_balance, xdai = %xdai_balance, "Balance check passed");

    ensure_weth_approval(c, gnosis_provider, wallet_address).await?;

    Ok(())
}

pub async fn ensure_weth_approval(c: &ValidatorConfig, gnosis_provider: DynProvider<Ethereum>, wallet_address: alloy::primitives::Address) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let weth_addr = c.chains.get(&100).expect("Gnosis").deposit_token
        .expect("Gnosis should use WETH");
    let weth = IWETH::new(weth_addr, gnosis_provider);
    let current_allowance = weth.allowance(wallet_address, c.outbox_arb_to_gnosis).call().await?;

    if current_allowance == U256::ZERO {
        info!(logger = "Startup", "No WETH approval found for Gnosis outbox, setting max approval");
        let max_approval = U256::MAX;
        let approve_tx = weth.approve(c.outbox_arb_to_gnosis, max_approval);
        let pending = approve_tx.send().await?;
        let receipt = pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await?;

        if !receipt.status() {
            panic!("FATAL: WETH approval transaction failed");
        }

        info!(logger = "Startup", "WETH max approval set for Gnosis outbox");
    } else {
        info!(logger = "Startup", allowance = %current_allowance, "WETH approval exists");
    }

    Ok(())
}

/// How far back to sample when measuring average block time. On chains shorter
/// than this the lookback is clamped to genesis and the divisor follows the
/// actual block delta, so the average stays correct instead of being skewed.
const BLOCK_TIME_SAMPLE_BLOCKS: u64 = 10_000;

async fn get_avg_block_time_ms(provider: &DynProvider<Ethereum>) -> u64 {
    let latest_block = crate::retry_rpc_opt("get latest block", || async { provider.get_block_by_number(Default::default()).await }).await
        .unwrap_or_else(|e| panic!("Failed to get latest block: {e}"))
        .expect("Latest block not found");
    let latest = latest_block.header.number;
    let old = latest.saturating_sub(BLOCK_TIME_SAMPLE_BLOCKS);
    let old_block = crate::retry_rpc_opt("get old block", || async { provider.get_block_by_number(old.into()).await }).await
        .unwrap_or_else(|e| panic!("Failed to get old block: {e}"))
        .expect("Old block not found");

    // `.max(1)` guards a genesis-only chain (latest == 0), where the delta is zero.
    let block_delta = latest.saturating_sub(old).max(1);
    let time_diff = latest_block.header.timestamp.saturating_sub(old_block.header.timestamp);
    (time_diff * 1000) / block_delta
}

pub async fn load_route_settings(
    route: &Route,
    arb_outbox_address: Address,
    arb_outbox_provider: &DynProvider<Ethereum>,
) -> RouteSettings {
    info!(logger = "Startup", route = route.name, "Loading route settings from contracts");

    let avg_block_time_ms = get_avg_block_time_ms(arb_outbox_provider).await;
    info!(logger = "Startup", route = route.name, avg_block_time_ms, "Block time computed");

    let arb_outbox = IOutbox::new(arb_outbox_address, arb_outbox_provider.clone());
    let rollup_address = crate::retry_rpc_or_panic("get rollup address from Arbitrum outbox", || async { arb_outbox.rollup().call().await }).await;
    let rollup = IRollup::new(rollup_address, arb_outbox_provider.clone());
    let confirm_period_blocks: u64 = crate::retry_rpc_or_panic("get confirmPeriodBlocks", || async { rollup.confirmPeriodBlocks().call().await }).await
        .max(14458);
    info!(logger = "Startup", route = route.name, confirm_period_blocks, "Rollup config loaded");

    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());
    let sequencer_delay_limit = crate::retry_rpc_or_panic("get sequencerDelayLimit", || async { outbox.sequencerDelayLimit().call().await }).await.to::<u64>();
    let min_challenge_period = crate::retry_rpc_or_panic("get minChallengePeriod", || async { outbox.minChallengePeriod().call().await }).await.to::<u64>();
    let epoch_period = crate::retry_rpc_or_panic("get epochPeriod", || async { outbox.epochPeriod().call().await }).await.to::<u64>();
    info!(logger = "Startup", route = route.name, sequencer_delay_limit, epoch_period, min_challenge_period, "Outbox params loaded");

    let relay_delay_secs = (confirm_period_blocks * avg_block_time_ms / 1000) + TIMING_SAFETY_BUFFER_SECS;
    let start_verification_delay = sequencer_delay_limit + epoch_period + TIMING_SAFETY_BUFFER_SECS;
    let min_challenge_period_with_buffer = min_challenge_period + TIMING_SAFETY_BUFFER_SECS;
    let sync_lookback_secs = relay_delay_secs + start_verification_delay + min_challenge_period_with_buffer + TIMING_SAFETY_BUFFER_SECS;

    info!(logger = "Startup", route = route.name, relay_delay_secs, start_verification_delay, min_challenge_period = min_challenge_period_with_buffer, sync_lookback_secs, "Route timing computed");

    RouteSettings {
        relay_delay_secs,
        start_verification_delay,
        min_challenge_period: min_challenge_period_with_buffer,
        sync_lookback_secs,
    }
}

/// Startup-path tests, driven by the in-process fault transport rather than a devnet.
///
/// `get_avg_block_time_ms` is private, so this has to live in-crate: it is also the one
/// startup computation that silently poisons everything downstream if it is wrong, since
/// `relay_delay_secs` is derived from it and an under-estimate schedules a relay before
/// the assertion can possibly have been confirmed.
#[cfg(test)]
mod tests {
    use super::*;
    use crate::contracts::{IOutbox, IRollup, IVeaOutbox};
    use crate::test_support::{Call, Fault, FaultTransport, address_word, block, word};
    use alloy::primitives::address;
    use alloy::sol_types::SolCall;

    /// Resolves the block tag of an `eth_getBlockByNumber` against a fixed chain head.
    fn tag_to_number(call: &Call, latest: u64) -> Option<u64> {
        match call.param(0).as_str()? {
            "latest" | "pending" | "safe" | "finalized" => Some(latest),
            "earliest" => Some(0),
            hex => u64::from_str_radix(hex.trim_start_matches("0x"), 16).ok(),
        }
    }

    /// A chain whose head is `latest` and whose block `n` has timestamp `ts(n)`.
    fn chain<T>(latest: u64, ts: T) -> FaultTransport
    where
        T: Fn(u64) -> u64 + Send + Sync + 'static,
    {
        FaultTransport::new(move |call| match tag_to_number(call, latest) {
            Some(n) if n <= latest => Fault::Ok(block(n, ts(n))),
            // Anything above the head is a block the node genuinely does not have yet.
            _ => Fault::null(),
        })
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_measures_the_full_sample_window() {
        // 250ms blocks, the Arbitrum figure the route timings are sized around.
        let t = chain(10_500, |n| 1_000_000 + n / 4);

        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 250);
        assert_eq!(t.count_of("eth_getBlockByNumber"), 2, "one head sample, one lookback sample");
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_clamps_the_lookback_to_genesis_on_a_short_chain() {
        // A 100-block chain is shorter than BLOCK_TIME_SAMPLE_BLOCKS. An unclamped
        // `latest - 10_000` underflows (panic in debug, a ~1.8e19 block number in
        // release, which the node answers `null` to). 12s blocks over 100 blocks.
        let t = chain(100, |n| 1_000 + 12 * n);

        // 12000, not 120: the divisor has to be the *actual* delta of 100 blocks, not
        // the 10_000 constant, or a fresh devnet reports 100x-too-fast blocks and
        // `relay_delay_secs` collapses to well under the confirmation period.
        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 12_000);
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_survives_a_genesis_only_chain() {
        // latest == 0: the block delta is zero, and only the `.max(1)` keeps this from
        // being a divide-by-zero panic in the very first thing startup does.
        let t = chain(0, |_| 1_700_000_000);

        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 0);
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_retries_a_null_head_instead_of_panicking() {
        // A node mid-sync answers `null` for the head it is about to have. The first
        // call is nulled, the retry must recover rather than hitting the `.expect`.
        let t = FaultTransport::new(|call| match call.method_index {
            0 => Fault::null(),
            _ => match tag_to_number(call, 10_500) {
                Some(n) => Fault::Ok(block(n, 1_000_000 + n / 4)),
                None => Fault::null(),
            },
        });

        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 250);
        assert_eq!(t.count_of("eth_getBlockByNumber"), 3, "one nulled head, then head + lookback");
    }

    /// Outbox parameters, as a fault script over `eth_call`.
    fn outbox_params(
        sequencer_delay_limit: u64,
        min_challenge_period: u64,
        epoch_period: u64,
    ) -> FaultTransport {
        FaultTransport::new(move |call| {
            if call.selector_is(IVeaOutbox::sequencerDelayLimitCall::SELECTOR) {
                Fault::Ok(word(sequencer_delay_limit))
            } else if call.selector_is(IVeaOutbox::minChallengePeriodCall::SELECTOR) {
                Fault::Ok(word(min_challenge_period))
            } else if call.selector_is(IVeaOutbox::epochPeriodCall::SELECTOR) {
                Fault::Ok(word(epoch_period))
            } else {
                Fault::Transport(alloy::transports::TransportErrorKind::custom_str(
                    "unexpected call on the outbox chain",
                ))
            }
        })
    }

    /// Arbitrum side: block sampling plus the rollup lookup and its confirm period.
    fn arb_chain(rollup: alloy::primitives::Address, confirm_period_blocks: u64) -> FaultTransport {
        FaultTransport::new(move |call| {
            if call.method == "eth_getBlockByNumber" {
                return match tag_to_number(call, 10_500) {
                    Some(n) => Fault::Ok(block(n, 1_000_000 + n / 4)),
                    None => Fault::null(),
                };
            }
            if call.selector_is(IOutbox::rollupCall::SELECTOR) {
                Fault::Ok(address_word(rollup))
            } else if call.selector_is(IRollup::confirmPeriodBlocksCall::SELECTOR) {
                Fault::Ok(word(confirm_period_blocks))
            } else {
                Fault::Transport(alloy::transports::TransportErrorKind::custom_str(
                    "unexpected call on the Arbitrum chain",
                ))
            }
        })
    }

    fn route(outbox: &FaultTransport, arb: &FaultTransport) -> Route {
        Route {
            name: "ARB_TO_ETH",
            inbox_chain_id: 42161,
            inbox_address: address!("0000000000000000000000000000000000000011"),
            inbox_provider: arb.provider(),
            inbox_avg_block_millis: 250,
            outbox_chain_id: 1,
            outbox_address: address!("0000000000000000000000000000000000000022"),
            outbox_provider: outbox.provider(),
            weth_address: None,
            settings: RouteSettings::test_defaults(),
        }
    }

    #[tokio::test(start_paused = true)]
    async fn route_settings_are_derived_from_the_contracts() {
        let rollup = address!("0000000000000000000000000000000000000033");
        let arb = arb_chain(rollup, 45_818);
        let outbox = outbox_params(86_400, 10_800, 7_200);
        let r = route(&outbox, &arb);

        let s = load_route_settings(
            &r,
            address!("0000000000000000000000000000000000000044"),
            &arb.provider(),
        )
        .await;

        // 45_818 blocks x 250ms = 11_454s, + the 10min safety buffer.
        assert_eq!(s.relay_delay_secs, 11_454 + 600);
        assert_eq!(s.start_verification_delay, 86_400 + 7_200 + 600);
        assert_eq!(s.min_challenge_period, 10_800 + 600);
        assert_eq!(
            s.sync_lookback_secs,
            (11_454 + 600) + (86_400 + 7_200 + 600) + (10_800 + 600) + 600
        );

        // The outbox params must come off the *outbox* chain, not the Arbitrum one:
        // reading `epochPeriod` from the wrong chain would mis-derive every epoch.
        assert_eq!(outbox.count_of("eth_call"), 3);
    }

    #[tokio::test(start_paused = true)]
    async fn confirm_period_is_floored_so_a_short_rollup_answer_cannot_shrink_the_relay_delay() {
        // A rollup (or a lying RPC) reporting a tiny confirmPeriodBlocks would otherwise
        // schedule the relay before the assertion could possibly be confirmed, and the
        // execute would revert against an Outbox root that is still zero.
        let rollup = address!("0000000000000000000000000000000000000033");
        let arb = arb_chain(rollup, 100);
        let outbox = outbox_params(86_400, 10_800, 7_200);
        let r = route(&outbox, &arb);

        let s = load_route_settings(
            &r,
            address!("0000000000000000000000000000000000000044"),
            &arb.provider(),
        )
        .await;

        // 14_458 blocks x 250ms = 3_614s, + the buffer - the floor, not 100 blocks.
        assert_eq!(s.relay_delay_secs, 3_614 + 600);
    }
}

