/// Tests for the retry layer.
///
/// All of these run on a paused tokio clock: `retry_rpc` sleeps 5+15+45 = 65 seconds
/// across a full exhaustion, and the schedule itself is part of what is being asserted,
/// so virtual time is both the fast and the precise option.
#[cfg(test)]
mod retry_tests {
    use super::*;
    use std::sync::{Arc, Mutex};
    use tokio::time::Instant;

    type BoxErr = Box<dyn std::error::Error + Send + Sync>;

    /// Records the virtual time of every attempt, so a test can assert the backoff
    /// schedule rather than just the attempt count.
    #[derive(Default)]
    struct Attempts {
        at: Mutex<Vec<Instant>>,
    }

    impl Attempts {
        /// Logs one attempt and returns its 0-based index.
        fn record(&self) -> usize {
            let mut at = self.at.lock().expect("attempt log");
            at.push(Instant::now());
            at.len() - 1
        }

        fn count(&self) -> usize {
            self.at.lock().expect("attempt log").len()
        }

        /// The delay observed before each retry, i.e. the applied backoff schedule.
        fn gaps(&self) -> Vec<Duration> {
            let at = self.at.lock().expect("attempt log");
            at.windows(2).map(|w| w[1] - w[0]).collect()
        }
    }

    #[tokio::test(start_paused = true)]
    async fn succeeds_without_sleeping_when_the_first_attempt_works() {
        let attempts = Arc::new(Attempts::default());
        let a = attempts.clone();
        let start = Instant::now();

        let out: Result<u64, BoxErr> = retry_rpc("healthy call", move || {
            let a = a.clone();
            async move {
                a.record();
                Ok(7)
            }
        })
        .await;

        assert_eq!(out.expect("first attempt succeeds"), 7);
        assert_eq!(attempts.count(), 1);
        assert_eq!(Instant::now() - start, Duration::ZERO, "a healthy call must not be delayed");
    }

    #[tokio::test(start_paused = true)]
    async fn retries_transient_failures_then_succeeds() {
        let attempts = Arc::new(Attempts::default());
        let a = attempts.clone();

        let out: Result<u64, BoxErr> = retry_rpc("flaky call", move || {
            let a = a.clone();
            async move {
                match a.record() {
                    0 | 1 => Err("error sending request: connection refused".into()),
                    _ => Ok(42),
                }
            }
        })
        .await;

        assert_eq!(out.expect("third attempt succeeds"), 42);
        assert_eq!(attempts.count(), 3, "must stop as soon as an attempt succeeds");
        assert_eq!(attempts.gaps(), RPC_RETRY_DELAYS[..2].to_vec());
    }

    #[tokio::test(start_paused = true)]
    async fn gives_up_after_max_attempts_on_the_documented_backoff() {
        let attempts = Arc::new(Attempts::default());
        let a = attempts.clone();
        let start = Instant::now();

        let out: Result<u64, BoxErr> = retry_rpc("dead endpoint", move || {
            let a = a.clone();
            async move {
                a.record();
                Err("error sending request: connection refused".into())
            }
        })
        .await;

        assert!(out.is_err(), "an endpoint that never answers must surface an error");
        assert_eq!(attempts.count(), RPC_MAX_ATTEMPTS);
        assert_eq!(attempts.gaps(), RPC_RETRY_DELAYS.to_vec());
        assert_eq!(Instant::now() - start, Duration::from_secs(5 + 15 + 45));
    }

    #[tokio::test(start_paused = true)]
    async fn propagates_the_final_error_string_verbatim() {
        // The dispatcher and the tasks route on `e.to_string() == "<sentinel>"`. If
        // `retry_rpc` ever wrapped or annotated the error it returns, those exact-match
        // arms would stop firing and tasks would get the wrong reschedule - or be dropped.
        for sentinel in [
            "EpochNotFinalized",
            "PendingReplacement",
            "NonceConsumed",
            "Insufficient funds",
            "VerificationStarted",
            "RootNotConfirmed",
            "ExecutionFailed",
        ] {
            let out: Result<(), BoxErr> =
                retry_rpc("sentinel call", || async move { Err(sentinel.into()) }).await;
            assert_eq!(
                out.expect_err("every attempt failed").to_string(),
                sentinel,
                "retry_rpc must not rewrite the sentinel the dispatcher matches on"
            );
        }

        // The outbox revert is matched by substring, so it has to survive intact too.
        let out: Result<(), BoxErr> = retry_rpc("reverting call", || async {
            Err("server returned an error response: execution reverted: Invalid claim.".into())
        })
        .await;
        assert!(
            out.expect_err("every attempt failed").to_string().contains("Invalid claim"),
            "the outbox revert string must reach the dispatcher's `contains` arm"
        );
    }

    #[tokio::test(start_paused = true)]
    async fn retry_rpc_opt_retries_a_null_answer_then_returns_the_value() {
        // A node that is mid-sync answers `null` for a block that exists, and is often the
        // fastest transport to answer precisely because it has no block to fetch.
        let attempts = Arc::new(Attempts::default());
        let a = attempts.clone();

        let out: Result<Option<u64>, BoxErr> = retry_rpc_opt("get block", move || {
            let a = a.clone();
            async move { Ok((a.record() >= 2).then_some(99)) }
        })
        .await;

        assert_eq!(out.expect("no transport error"), Some(99));
        assert_eq!(attempts.count(), 3);
        assert_eq!(attempts.gaps(), RPC_RETRY_DELAYS[..2].to_vec());
    }

    #[tokio::test(start_paused = true)]
    async fn retry_rpc_opt_returns_a_persistent_null_rather_than_inventing_an_error() {
        // Callers distinguish "block not found" from "RPC broken"; converting the last
        // `Ok(None)` into an `Err` would collapse that distinction.
        let attempts = Arc::new(Attempts::default());
        let a = attempts.clone();
        let start = Instant::now();

        let out: Result<Option<u64>, BoxErr> = retry_rpc_opt("get block", move || {
            let a = a.clone();
            async move {
                a.record();
                Ok(None)
            }
        })
        .await;

        assert_eq!(out.expect("a persistent null is not a transport error"), None);
        assert_eq!(attempts.count(), RPC_MAX_ATTEMPTS);
        assert_eq!(Instant::now() - start, Duration::from_secs(5 + 15 + 45));
    }

    #[tokio::test(start_paused = true)]
    async fn retry_rpc_opt_recovers_from_a_mix_of_errors_and_nulls() {
        let attempts = Arc::new(Attempts::default());
        let a = attempts.clone();

        let out: Result<Option<u64>, BoxErr> = retry_rpc_opt("get block", move || {
            let a = a.clone();
            async move {
                match a.record() {
                    0 => Err("error sending request: connection refused".into()),
                    1 => Ok(None),
                    _ => Ok(Some(5)),
                }
            }
        })
        .await;

        assert_eq!(out.expect("no transport error"), Some(5));
        assert_eq!(attempts.count(), 3);
    }

    #[tokio::test(start_paused = true)]
    async fn retry_rpc_opt_propagates_the_final_error_string_verbatim() {
        let out: Result<Option<u64>, BoxErr> =
            retry_rpc_opt("sentinel call", || async { Err("EpochNotFinalized".into()) }).await;

        assert_eq!(out.expect_err("every attempt failed").to_string(), "EpochNotFinalized");
    }
}

